package zw.ac.uz.dpdms.auth; import org.springframework.context.annotation.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.boot.CommandLineRunner;
@Configuration public class AuthConfiguration {@Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean CommandLineRunner seed(UserRepository users,PasswordEncoder encoder){return a->{seed(users,encoder,"national@dpdms.local","NATIONAL","",""); seed(users,encoder,"flood.recorder.ward1","RECORDER","FLOOD","Rushinga Ward 1"); seed(users,encoder,"flood.supervisor","SUPERVISOR","FLOOD",""); seed(users,encoder,"drought.recorder.ward1","RECORDER","DROUGHT","Rushinga Ward 1"); seed(users,encoder,"drought.supervisor","SUPERVISOR","DROUGHT","");};} private void seed(UserRepository r,PasswordEncoder e,String name,String role,String hazard,String ward){if(r.findByUsername(name).isEmpty()){AppUser u=new AppUser();u.username=name;u.passwordHash=e.encode("ChangeMe123!");u.role=role;u.hazard=hazard;u.ward=ward;r.save(u);}}}
